class Solution:
    def sumSubarrayMins(self, arr: List[int]) -> int:
        res = 0
        arr = [float('-inf')] + arr + [float('-inf')]
        stack = [0]
        for i in range(1, len(arr)):
            while arr[stack[-1]] > arr[i]:
                cur = stack.pop()
                left = cur - stack[-1]
                right = i - cur
                res += arr[cur] * left * right
            stack.append(i)
        return res % (10**9 + 7)

