    def isPossible(self, n: int, edges: list[list[int]]) -> bool:
        neighbors = [set() for _ in range(n)]
        for a, b in edges:
            a -= 1
            b -= 1
            neighbors[a].add(b)
            neighbors[b].add(a)

        odd = [i for i in range(n) if len(neighbors[i]) % 2 == 1]
        numOdd = len(odd)

        if numOdd == 0:
            return True
        if numOdd == 2:
            o1, o2 = odd
            if o2 not in neighbors[o1]:
                return True
            for k in range(n):
                if k != o1 and k != o2 and k not in neighbors[o1] and k not in neighbors[o2]:
                    return True
            return False
        if numOdd == 4:
            a, b, c, d = odd
            return ((b not in neighbors[a] and d not in neighbors[c]) or
                    (c not in neighbors[a] and d not in neighbors[b]) or
                    (d not in neighbors[a] and c not in neighbors[b]))
