        q = collections.deque([(0, 0, 0)])
        while q:
            d, i, j = q.popleft()
            if i == m - 1 and j == n - 1:
                return d
            for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                ci, cj = i + di, j + dj
                if 0 <= ci < m and 0 <= cj < n:
                    newd = d + grid[ci][cj]
                    if newd < distance[ci][cj]:
                        distance[ci][cj] = newd
                        if grid[ci][cj] == 1:
                            q.append((newd, ci, cj))
                        else:
                            q.appendleft((newd, ci, cj))
        return distance[m - 1][n - 1]

