class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if n1 == 0:
            return 0
        if not set(s2).issubset(set(s1)):
            return 0

        s1_count = s2_count = 0
        index = 0
        recall = {}

        while s1_count < n1:
            for c in s1:
                if c == s2[index]:
                    index += 1
                    if index == len(s2):
                        s2_count += 1
                        index = 0
            s1_count += 1
            if index in recall:
                pre_s1, pre_s2 = recall[index]
                in_loop_s1 = s1_count - pre_s1
                in_loop_s2 = s2_count - pre_s2
                break
            recall[index] = (s1_count, s2_count)
        else:
            return s2_count // n2

        result = pre_s2
        remaining = n1 - pre_s1
        result += (remaining // in_loop_s1) * in_loop_s2
        remaining %= in_loop_s1

        for _ in range(remaining):
            for c in s1:
                if c == s2[index]:
                    index += 1
                    if index == len(s2):
                        result += 1
                        index = 0

        return result // n2

