class Solution:
    def findComplement(self, num: int) -> int:
        if num == 0:
            return 1
        com = []
        while num > 0:
            if num % 2 == 1:
                com.append('0')
            else:
                com.append('1')
            num //= 2
        return int(''.join(reversed(com)), 2)

